```python
import os
from flask import Flask, request, send_file, jsonify, send_from_directory
from flask_cors import CORS
import requests
import io

app = Flask(__name__, static_folder='.')
CORS(app)

MODAL_URL = os.environ.get("MODAL_URL", "")

@app.route("/")
def index():
    return send_from_directory('.', 'index.html')

@app.route("/generate", methods=["POST"])
def generate():
    if 'image' not in request.files:
        return jsonify({"error": "No image provided"}), 400

    image_file = request.files['image']

    if image_file.filename == '':
        return jsonify({"error": "No file selected"}), 400

    if not image_file.content_type.startswith('image/'):
        return jsonify({"error": "File must be an image"}), 400

    try:
        image_file.seek(0)
        files = {'file': (image_file.filename, image_file.stream, image_file.content_type)}
        form_data = {
            'prompt': request.form.get('prompt', 'The scene comes to life with natural movement and realistic motion'),
            'negative_prompt': request.form.get('negative_prompt', 'worst quality, inconsistent motion, blurry, jittery, distorted'),
            'width': request.form.get('width', '768'),
            'height': request.form.get('height', '512'),
            'num_frames': request.form.get('num_frames', '121'),
            'num_inference_steps': request.form.get('num_inference_steps', '40'),
            'guidance_scale': request.form.get('guidance_scale', '4.0'),
            'frame_rate': request.form.get('frame_rate', '24.0')
        }

        response = requests.post(MODAL_URL, files=files, data=form_data, timeout=600)

        if response.status_code == 200:
            return send_file(
                io.BytesIO(response.content),
                mimetype='video/mp4',
                as_attachment=True,
                download_name='generated_video.mp4'
            )
        else:
            error_message = response.text if response.text else f"HTTP {response.status_code}"
            return jsonify({"error": f"Modal API error: {error_message}"}), response.status_code

    except requests.exceptions.Timeout:
        return jsonify({"error": "Request timeout - video generation took too long"}), 504
    except requests.exceptions.ConnectionError:
        return jsonify({"error": "Failed to connect to Modal API"}), 503
    except requests.exceptions.RequestException as e:
        return jsonify({"error": f"Request failed: {str(e)}"}), 500
    except Exception as e:
        return jsonify({"error": f"Server error: {str(e)}"}), 500

@app.route("/health", methods=["GET"])
def health():
    return jsonify({"status": "healthy", "modal_url": MODAL_URL}), 200

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000, debug=False)
